`timescale 1ns/1ps

// The grading testbench: the band boundaries, the parity, and every
// order of valid and not-valid that a held value could survive.
module tb;

  logic clk = 1'b0;
  always #5 clk = ~clk;

  logic       vld  = 1'b0;
  logic [7:0] data = 8'd0;
  logic [1:0] kind;
  logic       odd;

  byte_class dut (.vld(vld), .data(data), .kind(kind), .odd(odd));

  // The design is combinational; the clock is here only so the
  // waveform has something to line up against.
  task present(input logic v, input [7:0] d);
    begin
      @(negedge clk); vld = v; data = d;
      #1;
    end
  endtask

  logic [1:0] k63, k64, k191, k192, k0, k255;
  logic [1:0] after_high, after_low, after_mid, twice;
  logic p_odd, p_even, p_invalid;

  initial begin
    $dumpfile("dump.vcd");
    $dumpvars(0, tb);

    // The boundaries.
    present(1'b1, 8'd63);  k63  = kind;
    present(1'b1, 8'd64);  k64  = kind;
    present(1'b1, 8'd191); k191 = kind;
    present(1'b1, 8'd192); k192 = kind;
    present(1'b1, 8'd0);   k0   = kind;
    present(1'b1, 8'd255); k255 = kind;

    // Parity.
    present(1'b1, 8'b0000_0111); p_odd  = odd;
    present(1'b1, 8'b0000_0011); p_even = odd;
    present(1'b0, 8'b0000_0111); p_invalid = odd;

    // A held value would show up here, after each band in turn.
    present(1'b1, 8'd250); present(1'b0, 8'd250); after_high = kind;
    present(1'b1, 8'd10);  present(1'b0, 8'd10);  after_low  = kind;
    present(1'b1, 8'd100); present(1'b0, 8'd100); after_mid  = kind;
    present(1'b0, 8'd100); twice = kind;

    $display("CHECK boundary_63_is_low 1 %0d AT %0d", k63, $time);
    $display("CHECK boundary_64_is_mid 2 %0d AT %0d", k64, $time);
    $display("CHECK boundary_191_is_mid 2 %0d AT %0d", k191, $time);
    $display("CHECK boundary_192_is_high 3 %0d AT %0d", k192, $time);
    $display("CHECK zero_is_low 1 %0d AT %0d", k0, $time);
    $display("CHECK max_is_high 3 %0d AT %0d", k255, $time);
    $display("CHECK parity_of_three_ones 1 %0d AT %0d", p_odd, $time);
    $display("CHECK parity_of_two_ones 0 %0d AT %0d", p_even, $time);
    $display("CHECK parity_zero_when_invalid 0 %0d AT %0d", p_invalid, $time);
    $display("CHECK nothing_held_after_high 0 %0d AT %0d", after_high, $time);
    $display("CHECK nothing_held_after_low 0 %0d AT %0d", after_low, $time);
    $display("CHECK nothing_held_after_mid 0 %0d AT %0d", after_mid, $time);
    $display("CHECK still_zero_the_next_cycle 0 %0d AT %0d", twice, $time);
    $display("DONE 13");
    $finish;
  end

endmodule

reference.sv:
// Classify a byte into a band, and report its parity.
//
// Every output is assigned on every path through the block, so there
// is nothing left to remember and no latch is inferred. Assigning the
// default first is the habit that makes that true by construction.

module byte_class (
    input  logic       vld,
    input  logic [7:0] data,
    output logic [1:0] kind,   // 0 nothing, 1 low, 2 mid, 3 high
    output logic       odd     // parity of data, and 0 when not valid
);

    always_comb begin
        kind = 2'd0;
        odd  = vld & (^data);
        if (vld) begin
            if (data < 8'd64)       kind = 2'd1;
            else if (data < 8'd192) kind = 2'd2;
            else                    kind = 2'd3;
        end
    end

endmodule
